ALTER TABLE admins ADD COLUMN display_name TEXT NOT NULL DEFAULT '';
ALTER TABLE admins ADD COLUMN email TEXT NOT NULL DEFAULT '';
ALTER TABLE admins ADD COLUMN totp_policy TEXT NOT NULL DEFAULT 'required' CHECK(totp_policy IN ('required','optional','disabled'));
ALTER TABLE admins ADD COLUMN must_reset INTEGER NOT NULL DEFAULT 0;
ALTER TABLE admins ADD COLUMN temporary_expires INTEGER;
ALTER TABLE admins ADD COLUMN last_login TEXT;
CREATE UNIQUE INDEX admin_email_unique ON admins(lower(email)) WHERE email!='';
ALTER TABLE sessions ADD COLUMN stage TEXT NOT NULL DEFAULT 'ready';
CREATE TABLE recovery_codes(admin_id TEXT NOT NULL REFERENCES admins(id) ON DELETE CASCADE,code_hash TEXT NOT NULL,PRIMARY KEY(admin_id,code_hash));
CREATE TABLE ownership(id INTEGER PRIMARY KEY CHECK(id=1),owner_id TEXT NOT NULL UNIQUE REFERENCES admins(id));
INSERT INTO ownership SELECT 1,id FROM admins WHERE is_main=1;
DROP TRIGGER protect_main_role;
DROP TRIGGER protect_main_delete;
CREATE TRIGGER protect_owner_delete BEFORE DELETE ON admins WHEN OLD.id=(SELECT owner_id FROM ownership WHERE id=1) BEGIN SELECT RAISE(ABORT,'Owner is protected'); END;
CREATE TRIGGER protect_owner_role BEFORE UPDATE ON admins WHEN NEW.is_main != CASE WHEN NEW.id=(SELECT owner_id FROM ownership WHERE id=1) THEN 1 ELSE 0 END OR (NEW.is_main=1 AND (NEW.disabled!=0 OR NEW.must_reset!=0 OR NEW.totp_policy!='required' OR NEW.totp='')) BEGIN SELECT RAISE(ABORT,'Owner is protected'); END;
CREATE TRIGGER establish_owner AFTER INSERT ON admins WHEN NEW.is_main=1 BEGIN INSERT INTO ownership(id,owner_id) VALUES(1,NEW.id); END;
CREATE TRIGGER validate_transfer BEFORE UPDATE ON ownership WHEN NOT EXISTS(SELECT 1 FROM admins WHERE id=NEW.owner_id AND disabled=0 AND must_reset=0 AND totp!='') BEGIN SELECT RAISE(ABORT,'Target must be active and enrolled'); END;
CREATE TRIGGER transfer_owner AFTER UPDATE ON ownership BEGIN UPDATE admins SET is_main=0 WHERE id=OLD.owner_id; UPDATE admins SET is_main=1,totp_policy='required' WHERE id=NEW.owner_id; END;
CREATE TRIGGER preserve_owner BEFORE DELETE ON ownership BEGIN SELECT RAISE(ABORT,'Ownership cannot be removed'); END;
INSERT INTO records(kind,id,data) VALUES('security','main','{"requireTotp":false}');
